func:
// S2 – Étape 1 : décoder la trame brute et produire une mesure normalisée.
// Entrée : message du récepteur (ou de l'injecteur) sur pce92/uplink
//   { received_at, payload_hex, rssi, snr, source }
// Sortie 1 : mesure normalisée. Sortie 2 : trame rejetée.
const codec = global.get("codec");
if (!codec) {
    node.error("Codec S1 non chargé : ajouter codec dans functionGlobalContext (voir plateforme/flows/README.md)");
    node.status({ fill: "red", shape: "ring", text: "codec absent" });
    return null;
}

const entree = msg.payload || {};
const recuA = entree.received_at || new Date().toISOString(); // règle 4 : horodatage à la réception

function rejet(raison) {
    node.warn("Trame rejetée : " + raison);
    return [null, {
        topic: "pce92/evenements",
        payload: { type: "rejet", raison: raison, received_at: recuA,
                   payload_hex: entree.payload_hex || null, source: entree.source || null }
    }];
}

if (typeof entree.payload_hex !== "string") {
    return rejet("message sans payload_hex");
}
const hex = entree.payload_hex.replace(/\s+/g, "");
if (!/^[0-9a-fA-F]*$/.test(hex) || hex.length % 2 !== 0) {
    return rejet("payload_hex n'est pas de l'hexadécimal valide");
}

const octets = hex.match(/../g).map(h => parseInt(h, 16));
const res = codec.decodeUplink({ bytes: octets });
if (res.errors) {
    return rejet(res.errors.join(" ; "));
}

const d = res.data;
msg.topic = "pce92/mesures/" + d.node_id;
msg.payload = {
    node_id: d.node_id,
    received_at: recuA,
    water_mm: d.water_valid ? d.water_mm : null,  // null = mesure invalide (0xFFFF)
    water_valid: d.water_valid,
    batt_v: d.batt_v,                             // null = tension inconnue (0xFF)
    seq: d.seq,
    alert: d.alert,
    next_min: d.next_min,                         // null = inconnu (0xFF)
    expected_next_at: d.next_min === null ? null
        : new Date(Date.parse(recuA) + d.next_min * 60000).toISOString(),
    rssi: entree.rssi ?? null,
    snr: entree.snr ?? null,
    source: entree.source ?? null,
    payload_hex: hex.toUpperCase(),
    warnings: res.warnings
};
if (res.warnings.length) {
    node.warn("Nœud " + d.node_id + ", seq " + d.seq + " : " + res.warnings.join(" ; "));
}
node.status({ fill: d.alert ? "red" : "green", shape: "dot",
              text: "nœud " + d.node_id + " · seq " + d.seq + " · " + (d.water_valid ? d.water_mm + " mm" : "invalide") });
return [msg, null];

// S2 – Étape 2 : contrôler le compteur seq (règle 5 du contrat).
// Écart = (seq - seq précédent) modulo 65536, par nœud :
//   = 1 : trame normale ; > 1 : trames perdues ; = 0 : doublon (écarté).
// Choix B1 (hors contrat) : un écart > 32768 est un retour en arrière du compteur
// (redémarrage du nœud ou trame en retard) : la mesure est gardée, sans compter de pertes.
// Sortie 1 : mesure acceptée. Sortie 2 : événement (doublon, pertes, retour en arrière).
const m = msg.payload;
const cle = "dernier_seq_" + m.node_id;
const precedent = flow.get(cle);
const ecart = precedent === undefined ? null : (m.seq - precedent + 65536) % 65536;

function evenement(type, details) {
    return {
        topic: "pce92/evenements",
        payload: Object.assign({ type: type, node_id: m.node_id, seq: m.seq, received_at: m.received_at }, details)
    };
}

if (ecart === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "doublon écarté · nœud " + m.node_id + " · seq " + m.seq });
    return [null, evenement("doublon", {})];
}

let evt = null;
m.seq_gap = ecart;
m.lost_before = 0;
if (ecart !== null && ecart > 32768) {
    evt = evenement("retour_seq", { seq_precedent: precedent });
} else if (ecart !== null && ecart > 1) {
    m.lost_before = ecart - 1;
    evt = evenement("trames_perdues", { nombre: ecart - 1, seq_precedent: precedent });
}

flow.set(cle, m.seq);
node.status({ fill: m.lost_before ? "yellow" : "green", shape: "dot",
              text: "nœud " + m.node_id + " · seq " + m.seq + (m.lost_before ? " · " + m.lost_before + " perdue(s)" : "") });
return [msg, evt];
